import{_ as i,c as t,o as n,ag as r}from"./chunks/framework.DfL_BkQ-.js";const g=JSON.parse('{"title":"Nutzung","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/usage.md","filePath":"de/guide/usage.md","lastUpdated":1794112334000}'),a={name:"de/guide/usage.md"};function l(s,e,d,o,u,h){return n(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="nutzung" tabindex="-1">Nutzung <a class="header-anchor" href="#nutzung" aria-label="Permalink to &quot;Nutzung&quot;">​</a></h1><h2 id="grundlegende-navigation" tabindex="-1">Grundlegende Navigation <a class="header-anchor" href="#grundlegende-navigation" aria-label="Permalink to &quot;Grundlegende Navigation&quot;">​</a></h2><h3 id="bilder-offnen" tabindex="-1">Bilder öffnen <a class="header-anchor" href="#bilder-offnen" aria-label="Permalink to &quot;Bilder öffnen&quot;">​</a></h3><ul><li><strong>Ablage-Menü</strong>: Klicke auf Ablage &gt; Öffnen, um einzelne Bilder auszuwählen</li><li><strong>Ordneransicht</strong>: Klicke auf Ablage &gt; Ordner öffnen, um ein ganzes Verzeichnis zu durchsuchen</li><li><strong>Drag &amp; Drop</strong>: Ziehe Bilddateien oder Ordner direkt in das Fenster der App</li><li><strong>Chrome-Erweiterung</strong>: Klicke auf jeder Webseite auf das Erweiterungssymbol, um alle Bilder zu sehen</li></ul><h2 id="finder-sync-erweiterung" tabindex="-1">Finder-Sync-Erweiterung <a class="header-anchor" href="#finder-sync-erweiterung" aria-label="Permalink to &quot;Finder-Sync-Erweiterung&quot;">​</a></h2><h3 id="schnelle-bildverarbeitung-aus-dem-finder" tabindex="-1">Schnelle Bildverarbeitung aus dem Finder <a class="header-anchor" href="#schnelle-bildverarbeitung-aus-dem-finder" aria-label="Permalink to &quot;Schnelle Bildverarbeitung aus dem Finder&quot;">​</a></h3><p>Die Finder-Sync-Erweiterung fügt deiner Finder-Symbolleiste eine Nicasa-Schaltfläche für die schnelle Bildverarbeitung hinzu:</p><ol><li>Wähle ein oder mehrere Bilder im Finder aus</li><li>Klicke auf die Nicasa-Schaltfläche in der Symbolleiste</li><li>Wähle <strong>Bildoptimierer</strong>, um Dateien zu komprimieren, oder <strong>KI-Bildeditor</strong>, um Bilder zu verbessern</li><li>Nicasa öffnet sich automatisch und verarbeitet die ausgewählten Dateien</li></ol><h3 id="unterstutzte-formate" tabindex="-1">Unterstützte Formate <a class="header-anchor" href="#unterstutzte-formate" aria-label="Permalink to &quot;Unterstützte Formate&quot;">​</a></h3><p>Die Erweiterung funktioniert mit JPG-, PNG-, GIF-, BMP-, WebP-, SVG-, TIFF- und ICO-Dateien.</p><h3 id="miniaturansicht" tabindex="-1">Miniaturansicht <a class="header-anchor" href="#miniaturansicht" aria-label="Permalink to &quot;Miniaturansicht&quot;">​</a></h3><p>Die Hauptoberfläche zeigt Miniaturansichten deiner Bilder:</p><ul><li><strong>Klicken</strong>: ein Bild auswählen</li><li><strong>Doppelklicken</strong>: in der Vollansicht öffnen</li><li><strong>Rechtsklicken</strong>: Kontextmenü mit Optionen aufrufen</li></ul><h3 id="vollansicht" tabindex="-1">Vollansicht <a class="header-anchor" href="#vollansicht" aria-label="Permalink to &quot;Vollansicht&quot;">​</a></h3><p>Beim Ansehen eines Bildes im Vollbild:</p><ul><li><strong>Zoom</strong>: Mausrad oder Zoom-Steuerelemente verwenden</li><li><strong>Verschieben</strong>: Klicken und ziehen, um vergrößerte Bilder zu bewegen</li><li><strong>Wechseln</strong>: Pfeiltasten oder Schaltflächen auf dem Bildschirm für vorheriges/nächstes Bild</li></ul><h2 id="screenshot-funktion" tabindex="-1">Screenshot-Funktion <a class="header-anchor" href="#screenshot-funktion" aria-label="Permalink to &quot;Screenshot-Funktion&quot;">​</a></h2><h3 id="screenshots-erstellen" tabindex="-1">Screenshots erstellen <a class="header-anchor" href="#screenshots-erstellen" aria-label="Permalink to &quot;Screenshots erstellen&quot;">​</a></h3><ol><li>Klicke auf die Screenshot-Schaltfläche in der Symbolleiste oder verwende das Tastaturkürzel</li><li>Wähle den Bereich aus, den du erfassen möchtest</li><li>Der Screenshot öffnet sich automatisch in Nicasa zur Bearbeitung</li></ol><h3 id="berechtigung-zur-bildschirmaufnahme" tabindex="-1">Berechtigung zur Bildschirmaufnahme <a class="header-anchor" href="#berechtigung-zur-bildschirmaufnahme" aria-label="Permalink to &quot;Berechtigung zur Bildschirmaufnahme&quot;">​</a></h3><p>Für die Screenshot-Funktion benötigt Nicasa die Berechtigung zur Bildschirmaufnahme:</p><ol><li>Gehe zu Systemeinstellungen &gt; Datenschutz &amp; Sicherheit &gt; Bildschirmaufnahme</li><li>Setze ein Häkchen neben Nicasa</li><li>Starte Nicasa bei Bedarf neu</li></ol><h2 id="ki-bildeditor" tabindex="-1">KI-Bildeditor <a class="header-anchor" href="#ki-bildeditor" aria-label="Permalink to &quot;KI-Bildeditor&quot;">​</a></h2><h3 id="uberblick-uber-den-ki-editor" tabindex="-1">Überblick über den KI-Editor <a class="header-anchor" href="#uberblick-uber-den-ki-editor" aria-label="Permalink to &quot;Überblick über den KI-Editor&quot;">​</a></h3><p>Nicasa enthält leistungsstarke KI-Werkzeuge zur Bildverbesserung:</p><ul><li><strong>Automatische Verbesserung</strong>: Bildqualität automatisch steigern</li><li><strong>Intelligentes Zuschneiden</strong>: intelligente Zuschnittvorschläge</li><li><strong>Farbkorrektur</strong>: KI-gestützte Farbanpassungen</li><li><strong>Rauschreduzierung</strong>: Rauschen und Körnung entfernen</li><li><strong>Schärfen</strong>: intelligentes Schärfen ohne Artefakte</li></ul><h3 id="inpainting-werkzeug" tabindex="-1">Inpainting-Werkzeug <a class="header-anchor" href="#inpainting-werkzeug" aria-label="Permalink to &quot;Inpainting-Werkzeug&quot;">​</a></h3><p>Das Inpainting-Werkzeug ermöglicht dir:</p><ul><li>unerwünschte Objekte aus Bildern zu entfernen</li><li>fehlende Bereiche intelligent zu füllen</li><li>beschädigte Bereiche wiederherzustellen</li><li>Hintergründe zu bereinigen</li></ul><h2 id="transparenter-overlay-modus" tabindex="-1">Transparenter Overlay-Modus <a class="header-anchor" href="#transparenter-overlay-modus" aria-label="Permalink to &quot;Transparenter Overlay-Modus&quot;">​</a></h2><p>Perfekt für Designer und Künstler:</p><ol><li>Öffne ein Bild in Nicasa</li><li>Aktiviere den Overlay-Modus im Menü „Darstellung“</li><li>Passe die Transparenz mit dem Schieberegler an</li><li>Das Bild bleibt über allen anderen Fenstern</li><li>Nutze es zum Nachzeichnen, für Referenzarbeit oder UI-Vergleiche</li></ol><h2 id="tastaturkurzel" tabindex="-1">Tastaturkürzel <a class="header-anchor" href="#tastaturkurzel" aria-label="Permalink to &quot;Tastaturkürzel&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Kürzel</th><th>Aktion</th></tr></thead><tbody><tr><td><code>Cmd+O</code></td><td>Datei öffnen</td></tr><tr><td><code>Cmd+Shift+O</code></td><td>Ordner öffnen</td></tr><tr><td><code>Space</code></td><td>Nächstes Bild</td></tr><tr><td><code>Shift+Space</code></td><td>Vorheriges Bild</td></tr><tr><td><code>Cmd+F</code></td><td>Vollbild umschalten</td></tr><tr><td><code>Cmd+W</code></td><td>Fenster schließen</td></tr><tr><td><code>Cmd+Q</code></td><td>App beenden</td></tr><tr><td><code>Delete</code></td><td>Aktuelles Bild löschen</td></tr><tr><td><code>Cmd+S</code></td><td>Screenshot erstellen</td></tr><tr><td><code>Cmd+E</code></td><td>KI-Editor öffnen</td></tr><tr><td><code>Cmd+T</code></td><td>Overlay-Modus umschalten</td></tr></tbody></table><h2 id="integration-der-chrome-erweiterung" tabindex="-1">Integration der Chrome-Erweiterung <a class="header-anchor" href="#integration-der-chrome-erweiterung" aria-label="Permalink to &quot;Integration der Chrome-Erweiterung&quot;">​</a></h2><h3 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h3><ol><li>Installiere die <a href="https://chromewebstore.google.com/detail/nicasa-image-viewer/cihceekeiedkinpjjjfehlgjdhpeokbj" target="_blank" rel="noreferrer">Nicasa Chrome-Erweiterung</a></li><li>Das Erweiterungssymbol erscheint in der Symbolleiste deines Browsers</li></ol><h3 id="nutzung-1" tabindex="-1">Nutzung <a class="header-anchor" href="#nutzung-1" aria-label="Permalink to &quot;Nutzung&quot;">​</a></h3><ol><li>Besuche eine beliebige Webseite</li><li>Klicke auf das Nicasa-Erweiterungssymbol</li><li>Sieh alle Bilder der Seite in einem Raster</li><li>Klicke auf ein Bild, um es in Nicasa zu öffnen</li><li>Nutze alle Nicasa-Funktionen für Webbilder</li></ol><h2 id="einstellungen" tabindex="-1">Einstellungen <a class="header-anchor" href="#einstellungen" aria-label="Permalink to &quot;Einstellungen&quot;">​</a></h2><p>Öffne die Einstellungen über Nicasa &gt; Einstellungen:</p><ul><li><strong>Allgemein</strong>: Standardordner, Sprache, Design</li><li><strong>Anzeige</strong>: Miniaturgröße, Zoomverhalten, Animationen</li><li><strong>Editor</strong>: Einstellungen für KI-Werkzeuge, Standardverbesserungen</li><li><strong>Erweiterungen</strong>: Einstellungen der Chrome-Erweiterung</li><li><strong>Datenschutz</strong>: Einstellungen zur Datenerfassung</li></ul><h2 id="unterstutzte-formate-1" tabindex="-1">Unterstützte Formate <a class="header-anchor" href="#unterstutzte-formate-1" aria-label="Permalink to &quot;Unterstützte Formate&quot;">​</a></h2><p>Nicasa unterstützt alle gängigen Bildformate:</p><ul><li><p><strong>Standard</strong>: JPEG, PNG, GIF, BMP, TIFF, WebP</p></li><li><p><strong>RAW</strong>: CR2, NEF, ARW, DNG (mit Konvertierung)</p></li><li><p><strong>Vektor</strong>: SVG (mit Rasterung)</p></li><li><p><strong>Animiert</strong>: GIF, APNG</p></li><li><p>JPEG/JPG</p></li><li><p>PNG</p></li><li><p>GIF (statisch)</p></li><li><p>BMP</p></li><li><p>TIFF</p></li><li><p>WebP</p></li><li><p>HEIC (auf unterstützten Systemen)</p></li></ul><h2 id="tipps-und-tricks" tabindex="-1">Tipps und Tricks <a class="header-anchor" href="#tipps-und-tricks" aria-label="Permalink to &quot;Tipps und Tricks&quot;">​</a></h2><ul><li>Nutze die Suchleiste, um Bilder schnell nach Dateinamen zu finden</li><li>Erstelle Sammlungen, indem du Bilder in Ordnern organisierst</li><li>Nutze das Bewertungssystem, um Lieblingsbilder zu markieren</li><li>Exportiere Bilder in verschiedenen Formaten über das Ablage-Menü</li></ul>',47)])])}const m=i(a,[["render",l]]);export{g as __pageData,m as default};
